package dev.pocketengine.features.teams;

import dev.pocketengine.core.CapabilityPort;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.remote.RemoteAssignmentWorkspaces;
import dev.pocketengine.features.remote.RemoteModule;
import dev.pocketengine.store.TaskStore;
import java.util.concurrent.Executor;
import java.util.function.Consumer;
import org.json.JSONArray;
import org.json.JSONObject;

/** Original member Runner schedules an actual selected Codex author; it cannot synthesize that author's files. */
public final class TeamRemoteProduction implements TeamAssignmentHost.RemoteProduction {
    public static final String PREPARE="team_prepare_remote_workspace",SUBMIT="team_submit_remote_job",QUERY="team_query_remote_job",FREEZE="team_freeze_remote_contribution",IMPORT="team_import_remote_contribution",CANCEL="team_cancel_remote_job";
    private final TaskStore tasks;private final RemoteAssignmentWorkspaces remote;private final TeamWorkFiles.Workspace workspace;private final Executor cleanup;private final Consumer<String> changed;
    /** Retention pin only. SQL and original server receipts remain the execution/resource authority. */
    private final java.util.concurrent.ConcurrentHashMap<String,String> unsettled=new java.util.concurrent.ConcurrentHashMap<>();
    public TeamRemoteProduction(TaskStore tasks,RemoteModule module,TeamWorkFiles.Workspace workspace,Executor originalControlQueue,Consumer<String> changed){this.tasks=java.util.Objects.requireNonNull(tasks);remote=new RemoteAssignmentWorkspaces(module);this.workspace=java.util.Objects.requireNonNull(workspace);cleanup=java.util.Objects.requireNonNull(originalControlQueue);this.changed=java.util.Objects.requireNonNull(changed);}
    @Override public RemoteAssignmentWorkspaces.Selection captureSelection(JSONObject reviewedMember,JSONArray nativeFiles)throws Exception {JSONObject selected=reviewedMember.getJSONObject("remoteProduction"),device=reviewedMember.getJSONObject("device");return remote.captureSelection(tasks,selected.getString("sourceTaskId"),selected.getString("snapshotId"),device.getString("profileId"),device.getString("environmentId"),nativeFiles,selected.getJSONObject("limits"),reviewedMember.optString("model"),selected.getBoolean("internalInferenceBillingUnboundedAcknowledged"));}
    @Override public RemoteAssignmentWorkspaces.Selection captureRevisionSelection(TaskStore.TeamRemoteRevisionSource source,JSONArray actualFiles)throws Exception{return remote.captureRevisionSelection(tasks,source,actualFiles);}
    @Override public JSONObject availability(TeamCoordinator.AssignmentCall call,JSONObject binding,RunControl original)throws Exception {
        call.checkCurrent();tasks.checkTeamAssignment(binding,"team_list_files",original);JSONObject scope=tasks.teamRemoteScopeSnapshot(binding.getString("taskId"));return new JSONObject(scope.toString()).put("available",!scope.optBoolean("needsOwnerScope",true)).put("message",scope.optBoolean("needsOwnerScope",true)?"请主人在原成员审阅所选文字文件副本、独立job额度、原父预算及内部计费未知；尚未提交远端job":"原远端制作范围已明确批准；每次仍核原prepared/当前代次");
    }
    @Override public CapabilityPort bind(TeamCoordinator.AssignmentCall call,JSONObject binding,RunControl original,TeamWorkFiles localDraft)throws Exception {
        TaskStore.TeamRemoteContext context=tasks.teamRemoteContext(call,binding,original);return new Port(binding,original,localDraft,liveHost(context));
    }
    private RemoteAssignmentWorkspaces.NativeHost liveHost(TaskStore.TeamRemoteContext context){return new RemoteAssignmentWorkspaces.NativeHost(){
        public TaskStore.TeamRemoteContext context(){return context;}
        public JSONObject originalSnapshot(TaskStore.TeamRemoteContext selected)throws Exception{return tasks.originalTeamRemoteSnapshot(selected);}
        public TaskStore.TeamRemoteClaim originalClaim(TaskStore.TeamRemoteContext selected,String operation)throws Exception{return tasks.originalTeamRemoteClaim(selected,operation);}
        public TaskStore.TeamRemoteClaim claim(TaskStore.TeamRemoteAction action,String operation,JSONObject scope,RunControl original)throws Exception{return tasks.claimTeamRemoteAction(context,action,operation,scope,original);}
        public void beforeDispatch(TaskStore.TeamRemoteClaim claim,RunControl original)throws Exception{tasks.beforeTeamRemoteDispatch(claim,original);}
        public void record(TaskStore.TeamRemoteClaim claim,JSONObject actual)throws Exception{tasks.recordTeamRemoteReceipt(claim,actual);changed.accept(context.view().getJSONObject("nativeAssignment").getString("assignmentId"));String child=claim.view().optString("childTaskId");if(!child.isEmpty())changed.accept(child);}
        public void checkOriginalRead(TaskStore.TeamRemoteContext selected)throws Exception{tasks.checkOriginalTeamRemoteRead(selected);}
    };}
    @Override public void stop(String teamRunId,String memberId)throws Exception {
        JSONArray all=tasks.list();for(int i=0;i<all.length();i++){JSONObject child=all.getJSONObject(i),origin=child.optJSONObject("origin"),context=origin==null?null:origin.optJSONObject("context"),assignment=context==null?null:context.optJSONObject("nativeAssignment");if(origin==null||!origin.optString("kind").equals("team_remote_assignment")||assignment==null||!teamRunId.equals(assignment.optString("teamRunId"))||memberId!=null&&!memberId.isEmpty()&&!memberId.equals(assignment.optString("memberId")))continue;String id=child.getString("id");unsettled.put(id,assignment.getString("teamRunId"));cleanup.execute(()->cancelOriginal(id));}
    }
    @Override public boolean hasActiveWork(String teamRunId){return unsettled.containsValue(teamRunId);}
    /** Resource retention only: SQL still owns settlement. A terminal label/ACK without physical cleanup is not final. */
    private static boolean finalFence(JSONObject actual){if(!actual.optString("status").matches("completed|failed|cancelled|timed_out|blocked")||!Boolean.TRUE.equals(actual.opt("dispatchFenceFinal")))return false;if(Boolean.TRUE.equals(actual.opt("processStarted"))){JSONObject proof=actual.optJSONObject("processCleanupProof");return proof!=null&&Boolean.TRUE.equals(proof.opt("processGroupStoppedVerified"));}return Boolean.FALSE.equals(actual.opt("processStarted"))&&Boolean.TRUE.equals(actual.opt("notStartedConfirmed"));}
    private void cancelOriginal(String child){try{JSONObject task=tasks.get(child,false);TaskStore.TeamRemoteContext context=tasks.originalTeamRemoteContext(child);unsettled.put(child,context.view().getJSONObject("nativeAssignment").getString("teamRunId"));RemoteAssignmentWorkspaces.NativeHost host=liveHost(context);RemoteAssignmentWorkspaces.Execution execution=remote.restoreExecution(host,task.getJSONObject("origin").getString("preparedOperationId"));JSONObject actual=remote.inspect(host,execution);if(!finalFence(actual))actual=remote.cancel(host,execution,null,null);if(finalFence(actual))unsettled.remove(child);else unsettled.put(child,context.view().getJSONObject("nativeAssignment").getString("teamRunId"));changed.accept(child);}catch(Exception unavailable){/* Original SQL/remote reservation remains unknown. No new job, refund or invented stop. */}}
    private final class Port implements CapabilityPort {
        private final JSONObject binding;private final RunControl original;private final TeamWorkFiles local;private final RemoteAssignmentWorkspaces.NativeHost host;private final AutoCloseable liveFence;
        private RemoteAssignmentWorkspaces.Preparation prepared;private RemoteAssignmentWorkspaces.Execution execution;private RemoteAssignmentWorkspaces.Contribution contribution;private volatile boolean closed;private boolean jobFinal;
        Port(JSONObject binding,RunControl original,TeamWorkFiles local,RemoteAssignmentWorkspaces.NativeHost host)throws Exception {this.binding=new JSONObject(binding.toString());this.original=original;this.local=local;this.host=host;liveFence=original.retainAuthorityCheck(()->tasks.checkTeamRemoteScopeCurrent(host.context()));try{restoreOriginal();}catch(Exception failure){liveFence.close();throw failure;}}
        private void restoreOriginal()throws Exception {
            JSONObject task=tasks.get(binding.getString("taskId"),false);JSONArray related=task.optJSONArray("relatedTasks");for(int i=0;related!=null&&i<related.length();i++){JSONObject ref=related.getJSONObject(i);if(!ref.optString("feature").equals("remote")||ref.optString("parentOperationId").isEmpty())continue;JSONObject child=tasks.get(ref.getString("taskId"),false),origin=child.optJSONObject("origin");if(origin==null||!origin.optString("kind").equals("team_remote_assignment"))continue;TaskStore.TeamRemoteContext old=tasks.originalTeamRemoteContext(child.getString("id"));JSONObject oldView=old.view();if(!oldView.getJSONObject("nativeAssignment").getString("assignmentId").equals(binding.getString("assignmentId"))||oldView.getJSONObject("nativeAssignment").getInt("assignmentRevision")!=binding.getInt("assignmentRevision"))continue;
                if(execution!=null)throw new SecurityException("原分工存在多个远端job，必须先核对原关系，不能猜最近job");RemoteAssignmentWorkspaces.NativeHost read=liveHost(old);execution=remote.restoreExecution(read,origin.getString("preparedOperationId"));}
            JSONArray operations=task.getJSONArray("operations");String frozenOperation=null;TaskStore.TeamRemoteContext frozenContext=null;
            for(int i=0;i<operations.length();i++){JSONObject operation=operations.getJSONObject(i),receipt=operation.optJSONObject("receipt"),record=receipt==null?null:receipt.optJSONObject("teamRemote"),old=record==null?null:record.optJSONObject("context"),assignment=old==null?null:old.optJSONObject("nativeAssignment");if(assignment==null||assignment.optInt("assignmentRevision")!=binding.getInt("assignmentRevision")||!assignment.optString("assignmentId").equals(binding.getString("assignmentId")))continue;String id=operation.getString("operationId");
                if(record.optString("action").equals("PREPARE")){if(prepared!=null)throw new SecurityException("原分工存在多个物理准备操作，只能先核对原件，不猜最近副本");TaskStore.TeamRemoteContext read=tasks.originalTeamRemoteContextForOperation(binding.getString("taskId"),id);prepared=remote.restorePreparation(liveHost(read),id);}
                if(record.optString("action").equals("FREEZE")){if(frozenOperation!=null)throw new SecurityException("原分工存在多个冻结贡献，需主人明确原件");frozenOperation=id;frozenContext=tasks.originalTeamRemoteContextForOperation(binding.getString("taskId"),id);}
            }
            if(frozenOperation!=null){if(execution==null)throw new SecurityException("原贡献没有原job关系");contribution=remote.restoreContribution(liveHost(frozenContext),execution,frozenOperation);}
        }
        @Override public JSONArray tools()throws Exception {JSONArray out=new JSONArray(),nativeTools=local.tools();for(int i=0;i<nativeTools.length();i++){JSONObject tool=nativeTools.getJSONObject(i);if(localAllowed(tool.getJSONObject("function").getString("name")))out.put(tool);}JSONObject empty=new JSONObject().put("type","object").put("properties",new JSONObject()).put("additionalProperties",false);out.put(tool(PREPARE,"准备本分工的真实远端所选文字文件副本；不修改原项目。",empty));out.put(tool(SUBMIT,"将本分工交给已选真实Codex作者；只允许已明确批准的一次独立job，不传路径/环境/授权。",new JSONObject().put("type","object").put("properties",new JSONObject().put("prompt",new JSONObject().put("type","string").put("minLength",1).put("maxLength",8000))).put("required",new JSONArray().put("prompt")).put("additionalProperties",false)));out.put(tool(QUERY,"查询本分工原remote job；未知只查原ID，不新建替代job。",empty));out.put(tool(FREEZE,"对已经真实结束的原job冻结实际所选文件贡献。",empty));out.put(tool(IMPORT,"原生回读冻结贡献的准确字节并导入本成员真实隔离草稿；模型不提供正文，仍待独审唯一整合。",empty));out.put(tool(CANCEL,"请求停止本分工的原remote job，ACK不等实际终止。",empty));return out;}
        private JSONObject tool(String name,String description,JSONObject schema)throws Exception{return new JSONObject().put("type","function").put("function",new JSONObject().put("name",name).put("description",description).put("parameters",schema));}
        private boolean localAllowed(String name){return name!=null&&name.matches("team_(prepare_draft|list_files|read_file|read_dependency|request_input|send_message)");}
        @Override public boolean supports(String name){return localAllowed(name)||PREPARE.equals(name)||SUBMIT.equals(name)||QUERY.equals(name)||FREEZE.equals(name)||IMPORT.equals(name)||CANCEL.equals(name);}
        @Override public boolean sideEffecting(String name){return localAllowed(name)?local.sideEffecting(name):supports(name)&&!QUERY.equals(name);}
        @Override public void validate(String name,JSONObject args)throws Exception{if(localAllowed(name)){local.validate(name,args);return;}if(!supports(name))throw new SecurityException("没有此远端团队工具");if(SUBMIT.equals(name)){if(args.length()!=1||!args.has("prompt")||args.getString("prompt").trim().isEmpty()||args.getString("prompt").length()>8000)throw new SecurityException("远端制作只能提供当前分工的有限prompt");}else if(args.length()!=0)throw new SecurityException("远端制作只选择原生ID，不能提供scope、bytes、审批或新预算");}
        @Override public JSONObject execute(String name,JSONObject input,RunControl control)throws Exception {
            try{return executeCurrent(name,input,control);}catch(Exception failure){String operation=input==null?"":input.optString("_hostOperationId");if(operation.matches("[a-f0-9-]{36}")){
                JSONObject task=tasks.get(binding.getString("taskId"),false);JSONArray operations=task.getJSONArray("operations");for(int i=0;i<operations.length();i++){JSONObject row=operations.getJSONObject(i);if(operation.equals(row.optString("operationId"))&&binding.getString("runId").equals(row.optString("runId"))&&name.equals(row.optString("tool"))&&row.optString("state").equals("prepared")&&row.optJSONObject("receipt")==null)return new JSONObject().put("ok",false).put("accepted",false).put("code","team_remote_preflight_rejected").put("requiresPause",true).put("message","原生预检未通过，原SQL确认该prepared尚未被claim或派发；请核对原分工/环境，不需要对账不存在的job。错误类型："+failure.getClass().getSimpleName());}
            }throw failure;}
        }
        private JSONObject executeCurrent(String name,JSONObject input,RunControl control)throws Exception {
            if(closed||control!=original)throw new SecurityException("不是原成员远端执行控制");original.check();if(localAllowed(name))return local.execute(name,input,control);
            JSONObject args=new JSONObject(input.toString());String operation=args.optString("_hostOperationId");args.remove("_hostOperationId");validate(name,args);if(sideEffecting(name)&&!operation.matches("[a-f0-9-]{36}")||!sideEffecting(name)&&!operation.isEmpty())throw new SecurityException("远端副作用必须由原Runner登记prepared操作，查询不能自填operation");
            if(PREPARE.equals(name)){if(prepared!=null){JSONObject known=prepared.view();return prepared.ready()?known.put("ok",true).put("known",true):waiting(known);}if(execution!=null)return new JSONObject().put("ok",true).put("known",true).put("message","原job已存在；无需重新准备或提交");prepared=remote.prepare(host,operation,original);JSONObject actual=prepared.view();return prepared.ready()?actual.put("ok",true):waiting(actual);}
            if(SUBMIT.equals(name)){if(execution!=null)return inspect();if(prepared==null||!prepared.ready())throw new SecurityException("先准备并核实原独立远端副本");execution=remote.submit(host,prepared,args.getString("prompt"),operation,original);JSONObject claim=execution.view();if(!claim.has("childTaskId"))return waiting(claim);unsettled.put(claim.getString("childTaskId"),binding.getString("teamRunId"));return waitForOriginalJob();}
            if(execution==null)throw new SecurityException("本分工尚无原native登记remote job");
            if(QUERY.equals(name))return inspect();if(CANCEL.equals(name))return remote.cancel(host,execution,operation,original);
            if(FREEZE.equals(name)){if(contribution!=null){JSONObject known=contribution.view();return known.has("assignmentContribution")?known.put("ok",true).put("known",true):waiting(known);}contribution=remote.freeze(host,execution,operation,original);JSONObject actual=contribution.view();return actual.has("assignmentContribution")?actual.put("ok",true):waiting(actual);}
            if(contribution==null)throw new SecurityException("先冻结原job的真实贡献，不导入当前可变workspace");return new TeamRemoteImports(remote,host,workspace,local,binding,original,()->tasks.checkTeamRemoteScopeCurrent(host.context())).execute(contribution,operation);
        }
        private JSONObject waitForOriginalJob()throws Exception {long until=System.nanoTime()+Math.multiplyExact(host.context().view().getJSONObject("limits").getLong("maxWallTimeSeconds")+15L,1_000_000_000L);while(true){original.check();JSONObject actual=inspect();if(jobFinal)return actual;if(System.nanoTime()>=until)return new JSONObject(actual.toString()).put("ok",false).put("status","unknown").put("accepted",JSONObject.NULL).put("code","team_remote_job_unknown").put("message","原job尚无确定终态；保留原child/operation与预算，仅核对不重提交");original.sleep(500);}}
        private JSONObject inspect()throws Exception {JSONObject actual=remote.inspect(host,execution);jobFinal=finalFence(actual);String child=execution.view().optString("childTaskId");if(!child.isEmpty()){if(jobFinal)unsettled.remove(child);else unsettled.put(child,binding.getString("teamRunId"));}return new JSONObject(actual.toString()).put("ok",actual.optString("status").equals("completed")).put("remoteAuthor",true).put("fullProject",false).put("commandChecksAvailable",false);}
        private JSONObject waiting(JSONObject actual)throws Exception {boolean approval=actual.optString("status").equals("awaiting_approval");return new JSONObject(actual.toString()).put("ok",false).put("accepted",approval?false:JSONObject.NULL).put("code",approval?"approval_required":"team_remote_operation_unknown").put("message",approval?"请主人审阅原远端job范围；尚未派发":"原远端动作尚无确定回执，只查询原operation，不重提交");}
        @Override public void close(){if(closed)return;closed=true;local.close();try{liveFence.close();}catch(Exception ignored){}if(execution!=null&&!jobFinal)try{String child=execution.view().optString("childTaskId");if(!child.isEmpty()){unsettled.put(child,binding.getString("teamRunId"));cleanup.execute(()->cancelOriginal(child));}}catch(Exception ignored){/* Original unknown remains reserved. */}}
    }
}
